import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import QRCode from 'qrcode';

const WerewolfSetup = () => {
  const navigate = useNavigate();
  const [playerCount, setPlayerCount] = useState(6);
  const [titAlbertCount, setTitAlbertCount] = useState(2);
  const [specialRoles, setSpecialRoles] = useState({
    'Bhai looké': false,
    'Cliffeurd': false,
    'Agwa': false,
    'Longanis': false,
    'Tifi': false,
    'Sefvilaz': false,
    'Voler': false
  });
  const [error, setError] = useState('');
  const [qrCodeUrl, setQrCodeUrl] = useState('');
  const [serverUrl, setServerUrl] = useState('');

  useEffect(() => {
    // Get server info for QR code
    const fetchServerInfo = async () => {
      try {
        const response = await fetch('/api/server-info');
        const data = await response.json();
        const url = data.url;
        setServerUrl(url);
        
        // Generate QR code
        const qrUrl = await QRCode.toDataURL(url, {
          width: 200,
          margin: 2,
          color: {
            dark: '#4a5568',
            light: '#ffffff'
          }
        });
        setQrCodeUrl(qrUrl);
      } catch (err) {
        console.error('Failed to get server info:', err);
        // Fallback to localhost
        const fallbackUrl = `http://localhost:3000`;
        setServerUrl(fallbackUrl);
        const qrUrl = await QRCode.toDataURL(fallbackUrl, {
          width: 200,
          margin: 2,
          color: {
            dark: '#4a5568',
            light: '#ffffff'
          }
        });
        setQrCodeUrl(qrUrl);
      }
    };

    fetchServerInfo();
  }, []);

  const specialRolesList = [
    { id: 'Bhai looké', name: 'Bhai looké', description: 'The Seer - can see one player\'s role each night' },
    { id: 'Cliffeurd', name: 'Cliffeurd', description: 'The Doctor - can protect one player each night' },
    { id: 'Agwa', name: 'Agwa', description: 'The Bodyguard - can protect players during day phase' },
    { id: 'Longanis', name: 'Longanis', description: 'The Hunter - can eliminate someone when eliminated' },
    { id: 'Tifi', name: 'Tifi', description: 'The Witch - has save and kill potions' },
    { id: 'Sefvilaz', name: 'Sefvilaz', description: 'The Mayor - vote counts double' },
    { id: 'Voler', name: 'Voler', description: 'The Thief - can steal roles' }
  ];

  const getSelectedSpecialRoles = () => {
    return Object.keys(specialRoles).filter(role => specialRoles[role]);
  };

  const getMaxTitAlbert = () => {
    if (playerCount <= 4) return 1;
    if (playerCount <= 8) return 2;
    if (playerCount <= 12) return 3;
    return 4;
  };

  const validateSetup = () => {
    const selectedSpecialRoles = getSelectedSpecialRoles();
    const totalSpecialRoles = selectedSpecialRoles.length + titAlbertCount;
    
    if (totalSpecialRoles > playerCount) {
      return 'Too many special roles for the number of players!';
    }
    
    if (titAlbertCount < 1) {
      return 'Must have at least 1 Tit Albert!';
    }
    
    if (titAlbertCount > getMaxTitAlbert()) {
      return `Too many Tit Albert for ${playerCount} players! Maximum: ${getMaxTitAlbert()}`;
    }
    
    if (playerCount < 4) {
      return 'Need at least 4 players to play!';
    }
    
    if (playerCount > 15) {
      return 'Maximum 15 players supported!';
    }
    
    return null;
  };

  const handleSpecialRoleChange = (roleId) => {
    setSpecialRoles(prev => ({
      ...prev,
      [roleId]: !prev[roleId]
    }));
    setError('');
  };

  const handlePlayerCountChange = (count) => {
    setPlayerCount(count);
    
    // Auto-adjust Tit Albert count if needed
    const maxTitAlbert = count <= 4 ? 1 : count <= 8 ? 2 : count <= 12 ? 3 : 4;
    if (titAlbertCount > maxTitAlbert) {
      setTitAlbertCount(maxTitAlbert);
    }
    
    setError('');
  };

  const handleTitAlbertCountChange = (count) => {
    setTitAlbertCount(count);
    setError('');
  };

  const handleStartGame = () => {
    const validationError = validateSetup();
    if (validationError) {
      setError(validationError);
      return;
    }
    
    // Store game configuration in sessionStorage for the join page
    const gameConfig = {
      playerCount,
      titAlbertCount,
      specialRoles: getSelectedSpecialRoles()
    };
    
    sessionStorage.setItem('werewolfConfig', JSON.stringify(gameConfig));
    navigate('/join');
  };

  const getRemainingVillagers = () => {
    const selectedSpecialRoles = getSelectedSpecialRoles();
    return playerCount - titAlbertCount - selectedSpecialRoles.length;
  };

  return (
    <div className="container">
      <button 
        className="back-button"
        onClick={() => navigate('/')}
        title="Back to Main Menu"
      >
        ←
      </button>
      
      <div className="card">
        <h1 className="title">Werewolf Setup</h1>
        
        {error && <div className="error">{error}</div>}
        
        <div className="form-group">
          <label className="form-label">Number of Players</label>
          <select
            className="select"
            value={playerCount}
            onChange={(e) => handlePlayerCountChange(parseInt(e.target.value))}
          >
            {Array.from({ length: 12 }, (_, i) => i + 4).map(num => (
              <option key={num} value={num}>{num} players</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Number of Tit Albert (Werewolves)</label>
          <select
            className="select"
            value={titAlbertCount}
            onChange={(e) => handleTitAlbertCountChange(parseInt(e.target.value))}
          >
            {Array.from({ length: getMaxTitAlbert() }, (_, i) => i + 1).map(num => (
              <option key={num} value={num}>{num} Tit Albert</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Special Roles</label>
          <div style={{ marginBottom: '10px', fontSize: '0.9rem', color: '#718096' }}>
            Select additional roles for more interesting gameplay
          </div>
          
          {specialRolesList.map(role => (
            <div key={role.id} className="checkbox-container">
              <input
                type="checkbox"
                id={role.id}
                checked={specialRoles[role.id]}
                onChange={() => handleSpecialRoleChange(role.id)}
              />
              <label htmlFor={role.id} className="checkbox-label">
                <div>
                  <strong>{role.name}</strong>
                  <div style={{ fontSize: '0.9rem', color: '#718096', marginTop: '2px' }}>
                    {role.description}
                  </div>
                </div>
              </label>
            </div>
          ))}
        </div>

        <div style={{ 
          background: 'rgba(102, 126, 234, 0.1)', 
          padding: '15px', 
          borderRadius: '10px',
          marginBottom: '25px'
        }}>
          <h3 style={{ marginBottom: '10px', color: '#4a5568' }}>Game Summary</h3>
          <div style={{ color: '#2d3748' }}>
            <div>👥 Total Players: <strong>{playerCount}</strong></div>
            <div>🐺 Tit Albert (Werewolves): <strong>{titAlbertCount}</strong></div>
            <div>⭐ Special Roles: <strong>{getSelectedSpecialRoles().length}</strong></div>
            <div>🏘️ Vilazwas (Regular Villagers): <strong>{getRemainingVillagers()}</strong></div>
          </div>
        </div>

        <button
          className="button"
          onClick={handleStartGame}
          style={{ fontSize: '1.3rem', padding: '20px' }}
        >
          🎲 Start Game Setup
        </button>

        {qrCodeUrl && (
          <div className="qr-container">
            <h3 style={{ marginBottom: '15px', color: '#4a5568' }}>
              🔗 Players Join Here
            </h3>
            <div className="qr-code">
              <img src={qrCodeUrl} alt="Join Game QR Code" />
            </div>
            <div style={{ 
              fontSize: '0.9rem', 
              color: '#718096',
              marginTop: '10px',
              wordBreak: 'break-all'
            }}>
              {serverUrl}
            </div>
            <div style={{ 
              fontSize: '0.8rem', 
              color: '#a0aec0',
              marginTop: '5px'
            }}>
              Scan QR code or visit URL to join
            </div>
          </div>
        )}

        <div style={{ 
          marginTop: '25px', 
          padding: '15px',
          background: 'rgba(237, 137, 54, 0.1)',
          borderRadius: '10px',
          fontSize: '0.9rem',
          color: '#c05621'
        }}>
          <strong>💡 Tip:</strong> One person should be the moderator. 
          When joining the game, enter "moderator" as your name to access game controls.
        </div>
      </div>
    </div>
  );
};

export default WerewolfSetup;
